(function(){
  var LOGO = 'data:image/png;base64,';
  function applyLogo(){
    document.querySelectorAll('img.brand-logo').forEach(function(el){ el.src = LOGO; });
    document.querySelectorAll('link[rel="icon"],link[rel="apple-touch-icon"]').forEach(function(l){ l.href = LOGO; });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', applyLogo); } else { applyLogo(); }
})();